package com.opensocket.aievent.core.issuetracking.change;
import java.time.OffsetDateTime; import java.util.Objects; import com.opensocket.aievent.core.integration.identity.IntegrationRiskLevel;
public record ProviderActionCandidate(String tenantId,String candidateId,String conflictId,String observationId,String connectionId,String externalProjectId,String externalIssueId,ProviderActionCandidateType candidateType,IntegrationRiskLevel riskLevel,ProviderActionCandidateStatus status,String requestedCommandJson,String requestHash,String providerIdentityHash,boolean requiresReauthentication,boolean requiresApproval,String reviewedBy,OffsetDateTime reviewedAt,String approvedBy,OffsetDateTime approvedAt,String executedBy,OffsetDateTime executedAt,String executionEvidence,String decisionReason,String idempotencyKey,long version,String correlationId,OffsetDateTime createdAt,OffsetDateTime updatedAt) {
 public ProviderActionCandidate { tenantId=req(tenantId,"tenantId");candidateId=req(candidateId,"candidateId");conflictId=norm(conflictId);observationId=norm(observationId);connectionId=req(connectionId,"connectionId");externalProjectId=norm(externalProjectId);externalIssueId=req(externalIssueId,"externalIssueId");candidateType=Objects.requireNonNull(candidateType,"candidateType is required");riskLevel=riskLevel==null?IntegrationRiskLevel.UNKNOWN:riskLevel;status=Objects.requireNonNull(status,"status is required");requestedCommandJson=req(requestedCommandJson,"requestedCommandJson");requestHash=req(requestHash,"requestHash");providerIdentityHash=norm(providerIdentityHash);reviewedBy=norm(reviewedBy);approvedBy=norm(approvedBy);executedBy=norm(executedBy);executionEvidence=norm(executionEvidence);decisionReason=norm(decisionReason);idempotencyKey=req(idempotencyKey,"idempotencyKey");if(version<1)throw new IllegalArgumentException("version must be positive");correlationId=norm(correlationId);createdAt=Objects.requireNonNull(createdAt,"createdAt is required");updatedAt=Objects.requireNonNull(updatedAt,"updatedAt is required"); }
 private static String req(String v,String n){Objects.requireNonNull(v,n+" is required");String x=v.trim();if(x.isEmpty())throw new IllegalArgumentException(n+" is required");return x;} private static String norm(String v){return v==null?"":v.trim();}
}
